#!/usr/bin/env bash
# init.sh - restore this checkout after `git clean -ffxd`.
#
# Restores packages and the agent instruction files generated by aislop.
# Reports prerequisites instead of installing them.
#
# Usage:
#   git clean -ffxd && ./init.sh
#   git clean -ffxd && ./init.sh --build
#
# Every step is idempotent.
# Windows equivalents: init.ps1 and init.bat.

set -eu
set -o pipefail

repository_root="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$repository_root"
build_requested=0

for argument in "$@"; do
    case "$argument" in
        --build) build_requested=1 ;;
        -h|--help) sed -n '2,12p' "${BASH_SOURCE[0]}"; exit 0 ;;
        *) echo "unknown flag: $argument" >&2; exit 2 ;;
    esac
done

missing_prerequisites=()
completed_steps=()
have() { command -v "$1" >/dev/null 2>&1; }
aislop_runnable() { have aislop && aislop --version >/dev/null 2>&1; }

echo "Checking prerequisites..."
if have node; then
    printf '  %-20s %s\n' "Node.js" "$(node --version 2>/dev/null)"
else
    printf '  %-20s %s\n' "Node.js" "MISSING"
    missing_prerequisites+=("Node.js ^22.18 || >=24.11 - https://nodejs.org")
fi

if have pnpm; then
    printf '  %-20s %s\n' "pnpm" "$(pnpm --version 2>/dev/null)"
else
    printf '  %-20s %s\n' "pnpm" "MISSING"
    missing_prerequisites+=("pnpm - enable Corepack or see https://pnpm.io/installation")
fi

if have aislop; then
    if aislop_runnable; then
        printf '  %-20s %s\n' "aislop" "$(aislop --version 2>/dev/null)"
    else
        printf '  %-20s %s\n' "aislop" "on PATH, not runnable yet (agent files only)"
    fi
else
    printf '  %-20s %s\n' "aislop" "missing (agent files only)"
fi

if ! have node || ! have pnpm; then
    echo "Cannot restore packages without Node.js and pnpm." >&2
    for item in "${missing_prerequisites[@]}"; do echo "  - $item"; done
    exit 1
fi

echo
echo "Restoring packages..."
pnpm install --frozen-lockfile --ignore-scripts
completed_steps+=("Packages restored")

# Build before the agent instruction files: the documented fleet installation
# runs `aislop` through scripts/wrappers/aislop, which needs this checkout's
# dist/cli.js. Building last left the wrapper unusable at the hook step, so the
# restore failed before the build that would have fixed it.
if [ "$build_requested" -eq 1 ]; then
    echo
    echo "Building aislop..."
    pnpm build
    completed_steps+=("Build output restored")
fi

if aislop_runnable; then
    echo
    echo "Restoring agent instruction files..."
    aislop hook install claude --project
    completed_steps+=(".claude/AISLOP.md and .claude/CLAUDE.md restored")

    if have git; then
        settings_path='.claude/settings.json'
        if git diff --quiet -- "$settings_path" &&
            git diff --cached --quiet -- "$settings_path" &&
            [ -n "$(git status --porcelain -- "$settings_path")" ]; then
            git restore --worktree --source=HEAD -- "$settings_path"
            echo "Normalized line endings in .claude/settings.json."
        fi
    fi
elif have aislop; then
    echo
    echo "Skipping agent instruction files: aislop is on PATH but not runnable."
    echo "Build it (./init.sh --build), then run: aislop hook install claude --project"
    missing_prerequisites+=("aislop (agent files only) - on PATH but not runnable")
else
    echo
    echo "Skipping agent instruction files: aislop is not installed."
    echo "Once installed, run: aislop hook install claude --project"
    missing_prerequisites+=("aislop (agent files only) - see docs/installation.md")
fi

provisioner=""
for candidate in schoen-lab-onboard schoen-lab; do
    if have "$candidate"; then provisioner="$candidate"; break; fi
done
if [ -n "$provisioner" ]; then
    echo
    echo "Re-applying provisioned project settings..."
    if "$provisioner" apply auto-memory; then
        completed_steps+=("Project-scope provisioned settings re-applied")
    else
        echo "$provisioner apply auto-memory failed; continuing." >&2
    fi
fi

echo
echo "Done."
for step in "${completed_steps[@]}"; do echo "  $step"; done
if [ "${#missing_prerequisites[@]}" -gt 0 ]; then
    echo
    echo "Missing prerequisites (install manually):"
    for item in "${missing_prerequisites[@]}"; do echo "  - $item"; done
fi
if [ "$build_requested" -eq 0 ]; then
    echo
    echo "Next: ./init.sh --build, or pnpm test for the full test run."
fi
exit 0
